[CmdletBinding()]
param([Parameter(Mandatory)][string]$DiagnosticsPath,[Parameter(Mandatory)][string]$OutputDirectory)
$ErrorActionPreference='Stop';Set-StrictMode -Version Latest
function Assert($ok,$message){if(!$ok){throw $message}}
function Save($p,$s){New-Item (Split-Path $p) -ItemType Directory -Force|Out-Null;[IO.File]::WriteAllText($p,$s.TrimEnd()+"`n",[Text.UTF8Encoding]::new($false))}
function Pos($v){(@($v|ForEach-Object {([double]$_).ToString('0.000',[Globalization.CultureInfo]::InvariantCulture)}) -join ' ')}
function Num($v){([double]$v).ToString('0.###',[Globalization.CultureInfo]::InvariantCulture)}
function Range($a,$b){if($a -eq $b){return (Num $a)};return "$(Num $a)–$(Num $b)"}
$ai=Get-Content "$OutputDirectory/AI/Groups.json" -Raw|ConvertFrom-Json
$d=Get-Content $DiagnosticsPath -Raw|ConvertFrom-Json
Assert ((Get-FileHash $DiagnosticsPath).Hash -ceq $ai.diagnosticsSha256) 'Different capture'
Assert ($ai.PSObject.Properties.Name -notcontains 'firePointEvidence') 'Already applied'
$targets=@($d.entities|Where-Object prefab -match '/[^/]*MachineGun[^/]*\.et$'|ForEach-Object {[pscustomobject]@{sourceId=$_.sourceId;prefab=$_.prefab;name=[IO.Path]::GetFileNameWithoutExtension($_.prefab);worldPositionMeters=$_.worldPosition;positionStatus=$_.positionStatus}})
$oldPaths=@($ai.records|ForEach-Object {if($_.location){$_.location.path}else{'Ungrouped/Ungrouped.md'}}|Sort-Object -Unique)
foreach($p in $ai.records){
 if($p.location -and $p.location.category -eq 'patrols'){$p|Add-Member firePointCandidates @();continue}
 $candidates=@(@(foreach($t in $targets){Assert ($t.positionStatus -ceq 'resolved') 'Unresolved MachineGun position';$distance=[math]::Sqrt([math]::Pow($p.worldPositionMeters[0]-$t.worldPositionMeters[0],2)+[math]::Pow($p.worldPositionMeters[2]-$t.worldPositionMeters[2],2));if($distance -le 50){[pscustomobject]@{sourceId=$t.sourceId;prefab=$t.prefab;name=$t.name;worldPositionMeters=$t.worldPositionMeters;distanceMeters=$distance}}})|Sort-Object distanceMeters,sourceId)
 $p|Add-Member firePointCandidates $candidates
 if(!$candidates.Count){continue}
 $p|Add-Member beforeFirePointLocation $p.location
 $p.location=[pscustomobject]@{locationId='fire_points';name='Огневые точки';category='fire_points';path='FirePoints/FirePoints.md';method='nearest_MachineGun_prefab_within_50m_XZ';ownershipEstablished=$false}
}
$ai|Add-Member firePointEvidence ([ordered]@{diagnosticsSha256=(Get-FileHash $DiagnosticsPath).Hash;sourceCapturedAtUTC=$d.generatedAtUTC;selector='prefab filename contains MachineGun, case insensitive';radiusMeters=50;distanceMetric='XZ';selection='nearest then source ID; excludes Patrols; nested Waypoint has priority';targets=$targets;assignedPointCount=@($ai.records|Where-Object {$_.location -and $_.location.category -eq 'fire_points'}).Count;scope='entities retained in existing source diagnostics; not a complete weapon inventory';ownershipEstablished=$false})
$ai.normalizerVersion='ambient-ai-groups-0.7';$ai.matchingRule+='; nearest_MachineGun_within_50m_XZ_for_non_Patrols_only'
Save "$OutputDirectory/AI/Groups.json" ($ai|ConvertTo-Json -Depth 70)
$labels=[ordered]@{control_points='Контрольные точки';harbors='Доки';supply_depots='Склады припасов';settlements='Города и деревни';starting_bases='Стартовые базы';other='Другое';checkpoints='Checkpoint';patrols='Patrols';fire_points='Огневые точки';unassigned='Без локации'}
$section=[Collections.Generic.List[string]]::new();$section.Add('## Объекты по локациям');$section.Add('');$section.Add('«Всего бойцов» — суммарная численность при одной группе на каждую точку; диапазон учитывает случайный состав. Это не число одновременно активных бойцов.');$section.Add('');$section.Add('Patrols имеют приоритет; только для остальных точек проверяется ближайший префаб с MachineGun в имени в радиусе 50 м по X/Z. Прежняя категория сохраняется; соседство не подтверждает использование оружия. Точки с вложенными source-сущностями Waypoint (включая DefendWaypoint) выделены в Patrols независимо от прежней локации. Прежняя привязка сохранена в JSON и таблице Patrols. Наличие оборонительного Waypoint не означает движение по маршруту. Остальные назначения: подтверждённый предок CampaignRemnantsSupplyDepot, затем категории справочника припасов по прежним радиусам (склады 200 м, остальные 350 м по X/Z); для остатка — ближайший Checkpoint в 50 м. Каждая точка учитывается один раз.');$section.Add('')
$newPaths=@()
foreach($category in $labels.Keys){$groups=@($ai.records|Where-Object {if($category -eq 'unassigned'){!$_.location}else{$_.location -and $_.location.category -eq $category}}|Group-Object {if($_.location){$_.location.locationId}else{'unassigned'}}|Sort-Object Name);if(!$groups.Count){continue};$section.Add("### $($labels[$category])");$section.Add('');$section.Add('| Локация | Точек | Всего бойцов |');$section.Add('| --- | ---: | ---: |')
foreach($g in $groups){$loc=$g.Group[0].location;$name='Без локации';$path='Ungrouped/Ungrouped.md';if($loc){$name=$loc.name;$path=$loc.path};$newPaths+=$path;$min=($g.Group|Measure-Object unitCountMin -Sum).Sum;$max=($g.Group|Measure-Object unitCountMax -Sum).Sum;$section.Add("| [$name](Locations/$path) | $($g.Count) | $(Range $min $max) |")
$page=[Collections.Generic.List[string]]::new();$title=$name;if($loc -and $category -notin @('patrols','fire_points')){$title+=' — '+(Pos $loc.worldPositionMeters)};$page.Add("# $title");$page.Add('');$page.Add('[Группы ИИ — сводка](../../Summary.md)');$page.Add('')
if($category -eq 'fire_points'){$page.Add('Точки ИИ без вложенных Waypoint в пределах 50 м по X/Z от ближайшего MachineGun-префаба из диагностики. Это географический признак, не подтверждение использования пулемёта. Прежние категории и все кандидаты сохранены в JSON.');$page.Add('');$page.Add('| Точка | Выбор / тип | Бойцов | Координаты X Y Z, м | Префаб | Координаты префаба X Y Z, м | Расстояние, м | Прежняя категория / группа |');$page.Add('| --- | --- | ---: | --- | --- | --- | ---: | --- |')}elseif($category -eq 'patrols'){$page.Add('Точки с подтверждёнными вложенными Waypoint, включая оборонительные. Прежняя локация показана для ориентира; в её итогах эти точки больше не учитываются. Координаты всех Waypoint и цепочки родителей сохранены в JSON.');$page.Add('');$page.Add('| Точка | Выбор / тип | Бойцов | Координаты X Y Z, м | Прежняя локация | Вложенные Waypoint |');$page.Add('| --- | --- | ---: | --- | --- | --- |')}else{$page.Add('Привязка и выбранный якорь сохранены из распределения по справочнику припасов / Checkpoint. Точки с вложенными Waypoint перенесены в Patrols. Численность условная, при одной группе на точку.');$page.Add('');$page.Add('| Точка | Выбор / тип | Бойцов | Координаты X Y Z, м | Якорь X Y Z, м | До якоря, м |');$page.Add('| --- | --- | ---: | --- | --- | ---: |')}
foreach($p in $g.Group|Sort-Object id){$type=if($p.selectionMode -eq 'random'){'Случайный тип'}else{$p.configuredType};$tail='— | —';if($category -eq 'fire_points'){$t=$p.firePointCandidates[0];$previous='Без локации';if($p.beforeFirePointLocation){$previous=$labels[$p.beforeFirePointLocation.category]+' / '+$p.beforeFirePointLocation.name};$tail="$($t.name) | $(Pos $t.worldPositionMeters) | $(Num $t.distanceMeters) | $previous"}elseif($category -eq 'patrols'){$previous=if($p.previousLocation){$p.previousLocation.name}else{'Без локации'};$types=(@($p.nestedWaypoints|Group-Object className|Sort-Object Name|ForEach-Object {"$($_.Count) × $($_.Name)"}) -join '; ');$tail="$previous | $types"}elseif($p.location){$tail="$(Pos $p.location.distanceOriginPosition) | $(Num $p.location.distanceMeters)"};$page.Add("| $($p.name) | $type | $(Range $p.unitCountMin $p.unitCountMax) | $(Pos $p.worldPositionMeters) | $tail |")}
$page.Add('');$page.Add('[Исходные данные и привязки](../../Groups.json).');Save "$OutputDirectory/AI/Locations/$path" ($page -join "`n")
};$section.Add('')}
$root=[IO.Path]::GetFullPath("$OutputDirectory/AI/Locations")
foreach($path in $oldPaths|Where-Object {$_ -notin $newPaths}){$full=[IO.Path]::GetFullPath((Join-Path $root $path));Assert ($full.StartsWith($root+[IO.Path]::DirectorySeparatorChar)) 'Invalid deletion path';Remove-Item -LiteralPath $full}
$path="$OutputDirectory/AI/Summary.md";$text=Get-Content $path -Raw;$text=[regex]::Replace($text,'(?s)## Объекты по локациям.*?(?=## Выбор и активация)',[Text.RegularExpressions.MatchEvaluator]{param($m)($section -join "`n")+"`n"});Save $path $text
$world=Get-Content "$OutputDirectory/world.json" -Raw|ConvertFrom-Json;$world.normalizerVersion=$ai.normalizerVersion;Save "$OutputDirectory/world.json" ($world|ConvertTo-Json -Depth 30)
"Fire points: $($ai.firePointEvidence.assignedPointCount)"
